INSERT INTO `Products` VALUES (1,'Điện thoại Apple iPhone 15 Pro Max 256GB','Màn hình Super Retina XDR OLED 6.7 inch, chip Apple A17 Pro mạnh mẽ, khung viền titan cao cấp, camera 48MP zoom quang 5x.',1199.00,25,'/uploads/products/product-1.jpg','2029-01-10 00:00:00','2024-01-10 00:00:00','Mỹ (USA)','Apple','8938501230011','pieces',1,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(2,'Tai nghe chống ồn Sony WH-1000XM5','Tai nghe không dây chống ồn chủ động đỉnh cao, thời lượng pin 30 giờ, âm thanh Hi-Res Audio, microphone đàm thoại sắc nét.',349.00,15,'/uploads/products/product-2.jpg','2029-02-15 00:00:00','2024-02-15 00:00:00','Nhật Bản','Sony','8938501230028','pieces',1,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(3,'Laptop Apple MacBook Air 13.6 inch M2','Thiết kế siêu mỏng nhẹ, chip Apple M2 8 nhân, RAM 8GB, SSD 256GB, màn hình Liquid Retina tuyệt đẹp, pin kéo dài 18 tiếng.',999.00,18,'/uploads/products/product-3.jpg','2030-01-05 00:00:00','2024-01-05 00:00:00','Mỹ (USA)','Apple','8938501230035','pieces',1,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(4,'Đồng hồ thông minh Apple Watch Series 9','Màn hình Retina Always-On 2000 nits, chip S9 SiP thao tác Double Tap chạm hai lần, đo nhịp tim, ECG và nồng độ oxy trong máu.',399.00,30,'/uploads/products/product-4.jpg','2029-03-01 00:00:00','2024-03-01 00:00:00','Mỹ (USA)','Apple','8938501230042','pieces',1,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(5,'Loa Bluetooth Marshall Acton III','Loa Bluetooth để bàn thiết kế phong cách vintage hoài cổ, công suất 60W âm trường rộng, kết nối Bluetooth 5.2 nhanh chóng.',279.00,8,'/uploads/products/product-5.jpg','2029-02-20 00:00:00','2024-02-20 00:00:00','Vương quốc Anh','Marshall','8938501230059','pieces',1,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(6,'Chuột không dây Logitech MX Master 3S','Chuột công thái học cao cấp, cảm biến 8000 DPI trên mọi bề mặt, con lăn điện từ MagSpeed cuộn 1000 dòng/giây, click cực êm.',99.00,45,'/uploads/products/product-6.jpg','2029-03-10 00:00:00','2024-03-10 00:00:00','Thụy Sĩ','Logitech','8938501230066','pieces',1,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(7,'Áo Polo nam Cotton Pique thoáng khí','Chất liệu cotton dệt mắt chim cao cấp, co giãn 4 chiều, chống nhăn tự nhiên, thấm hút mồ hôi tốt, kiểu dáng lịch lãm.',29.50,85,'/uploads/products/product-7.jpg','2028-04-01 00:00:00','2024-04-01 00:00:00','Việt Nam','Coolmate','8938501230073','pieces',2,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(8,'Quần Jean nam Slim Fit co giãn','Vải denim cotton dày dặn co giãn nhẹ, form dáng ôm tôn dáng hiện đại, độ bền màu cao, khóa kéo YKK kim loại chống gỉ.',45.00,50,'/uploads/products/product-8.jpg','2028-03-15 00:00:00','2024-03-15 00:00:00','Việt Nam','An Phước','8938501230080','pieces',2,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(9,'Áo Hoodie Unisex nỉ lót bông mềm mại','Áo hoodie form rộng phong cách trẻ trung năng động, chất vải nỉ bông giữ ấm tối đa trong mùa lạnh, túi kangaroo phía trước rộng rãi.',38.00,40,'/uploads/products/product-9.jpg','2028-02-10 00:00:00','2024-02-10 00:00:00','Việt Nam','Dirty Coins','8938501230097','pieces',2,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(10,'Giày Sneaker Nike Air Force 1 \'07','Biểu tượng sneaker toàn cầu với tông màu trắng tinh khôi, đệm khí Nike Air êm ái đàn hồi tốt, bề mặt da trơn cao cấp dễ vệ sinh.',110.00,22,'/uploads/products/product-10.jpg','2029-01-20 00:00:00','2024-01-20 00:00:00','Việt Nam','Nike','8938501230103','pieces',2,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(11,'Balo chống nước đựng laptop Arctic Hunter','Balo đa năng có ngăn chống sốc chuyên dụng cho laptop 15.6 inch, chất liệu vải Oxford trượt nước bền bỉ, cổng sạc USB thông minh ngoài.',42.00,35,'/uploads/products/product-11.jpg','2029-03-05 00:00:00','2024-03-05 00:00:00','Hồng Kông','Arctic Hunter','8938501230110','pieces',2,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(12,'Kính mát phi công phân cực Ray-Ban Aviator','Kính mát gọng kim loại mạ vàng sang trọng, tròng phân cực polarized chống lóa và ngăn chặn 100% tia tử ngoại UVA/UVB gây hại.',165.00,9,'/uploads/products/product-12.jpg','2029-01-15 00:00:00','2024-01-15 00:00:00','Ý (Italy)','Luxottica','8938501230127','pieces',2,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(13,'Cà phê Arabica Cầu Đất Đà Lạt rang xay 500g','Hạt cà phê Arabica thượng hạng được thu hái thủ công tại độ cao 1500m, mùi hương nồng nàn quyến rũ, vị chua thanh thoát hậu ngọt.',12.50,65,'/uploads/products/product-13.jpg','2025-05-01 00:00:00','2024-05-01 00:00:00','Lâm Đồng, Việt Nam','Cầu Đất Farm','8938501230134','packs',3,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(14,'Trà Ô Long Kim Tuyên hảo hạng 250g','Búp trà xanh Ô Long chế biến theo công nghệ Đài Loan truyền thống, vị chát dịu êm, thoảng hương sữa hoa cỏ thơm ngọt tự nhiên.',16.00,45,'/uploads/products/product-14.jpg','2026-04-10 00:00:00','2024-04-10 00:00:00','Lâm Đồng, Việt Nam','Tâm Châu','8938501230141','boxes',3,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(15,'Hạt Macca sấy nứt vỏ Đắk Lắk loại 1 500g','Hạt macca sấy giòn thơm béo ngậy, giàu vitamin E, canxi và Omega-3 tốt cho hệ tim mạch và trí não, đi kèm dụng cụ tách vỏ.',14.00,55,'/uploads/products/product-15.jpg','2025-05-15 00:00:00','2024-05-15 00:00:00','Đắk Lắk, Việt Nam','Tây Nguyên Food','8938501230158','boxes',3,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(16,'Mật ong hoa rừng tràm nguyên chất U Minh 1000ml','Mật ong tự nhiên 100% từ rừng tràm U Minh nguyên sinh, màu cánh gián vàng óng, độ sánh đậm đặc, giàu chất kháng khuẩn tự nhiên.',21.00,28,'/uploads/products/product-16.jpg','2026-03-20 00:00:00','2024-03-20 00:00:00','Cà Mau, Việt Nam','U Minh Honey','8938501230165','liters',3,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(17,'Yến mạch nguyên hạt cán dẹt Quaker Oats 1kg','Yến mạch hữu cơ nhập khẩu trực tiếp từ Mỹ, giàu chất xơ hòa tan beta-glucan giúp no lâu, hỗ trợ giảm cân và bảo vệ tim mạch hiệu quả.',8.50,75,'/uploads/products/product-17.jpg','2025-10-01 00:00:00','2024-04-01 00:00:00','Mỹ (USA)','Quaker Oats','8938501230172','kg',3,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(18,'Socola đen Lindt Excellence 85% Cacao Thụy Sĩ 100g','Thanh sô cô la đen nguyên chất 85% cacao thượng hạng từ Thụy Sĩ, vị đắng dịu hòa quyện hương vị trái cây khô và gỗ sồi sang trọng.',6.80,90,'/uploads/products/product-18.jpg','2025-08-10 00:00:00','2024-02-10 00:00:00','Thụy Sĩ','Lindt & Sprüngli','8938501230189','pieces',3,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(19,'Nồi chiên không dầu Philips XXL 7.2L HD9285','Nồi chiên thông minh kết nối Wifi điều khiển từ xa, công nghệ Rapid Air giảm 90% chất béo, giỏ chiên dung tích lớn chế biến cả con gà.',189.00,16,'/uploads/products/product-19.jpg','2029-01-20 00:00:00','2024-01-20 00:00:00','Hà Lan','Philips','8938501230196','pieces',4,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(20,'Robot hút bụi lau nhà Roborock Q Revo','Lực hút 5500Pa cực mạnh, trạm sạc tự giặt và sấy khô giẻ lau bằng luồng khí nóng, cảm biến LiDAR lập bản đồ nhà 3D chính xác.',699.00,7,'/uploads/products/product-20.jpg','2029-03-01 00:00:00','2024-03-01 00:00:00','Trung Quốc','Roborock','8938501230202','pieces',4,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(21,'Bộ nồi chảo Inox 304 nguyên khối Elmich 4 món','Bộ nồi chảo inox 304 3 lớp đúc liền khối tỏa nhiệt đều và giữ nhiệt lâu, không sinh chất độc hại khi đun nấu, dùng tốt trên bếp từ.',125.00,20,'/uploads/products/product-21.jpg','2034-02-05 00:00:00','2024-02-05 00:00:00','Cộng hòa Séc','Elmich','8938501230219','boxes',4,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(22,'Máy xay sinh tố cầm tay Braun MultiQuick 5 MQ5235','Công suất mạnh 1000W với 21 tốc độ điều khiển thông minh, công nghệ lưỡi dao chuông xoắn PowerBell xay nhuyễn thực phẩm nhanh chóng.',79.00,31,'/uploads/products/product-22.jpg','2029-03-12 00:00:00','2024-03-12 00:00:00','Đức','Braun','8938501230226','pieces',4,'2026-09-24 10:46:47','2026-09-24 11:41:58'),(23,'Ấm siêu tốc thông minh Xiaomi Smart Kettle Pro','Bình đun nước siêu tốc dung tích 1.5L ruột inox 304 nguyên khối, màn hình kỹ thuật số hiển thị nhiệt độ, hỗ trợ giữ nhiệt đến 12 tiếng.',42.00,28,'/uploads/products/product-23.jpg','2029-04-05 00:00:00','2024-04-05 00:00:00','Trung Quốc','Xiaomi','8938501230233','pieces',4,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(24,'Máy lọc không khí Levoit Core 300S Smart HEPA','Bộ lọc HEPA H13 loại bỏ 99.97% hạt bụi siêu mịn PM2.5, phấn hoa và mùi hôi khó chịu, vận hành cực êm ái thích hợp cho phòng ngủ.',119.00,14,'/uploads/products/product-24.jpg','2029-02-18 00:00:00','2024-02-18 00:00:00','Mỹ (USA)','Levoit','8938501230240','pieces',4,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(25,'Kem chống nắng kiểm soát dầu La Roche-Posay Anthelios 50ml','Chống nắng quang phổ rộng SPF50+ bảo vệ da trước tia UVA/UVB dài, kiềm dầu suốt 8 giờ, kết cấu khô thoáng không bóng nhờn.',19.50,65,'/uploads/products/product-25.jpg','2027-03-01 00:00:00','2024-03-01 00:00:00','Pháp','La Roche-Posay','8938501230257','pieces',5,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(26,'Serum rau má Skin1004 Madagascar Centella 100ml','Tinh chất rau má nguyên chất 100% từ vùng đảo Madagascar giúp làm dịu nốt mụn, phục hồi và củng cố hàng rào bảo vệ da khỏe mạnh.',15.00,50,'/uploads/products/product-26.jpg','2027-04-15 00:00:00','2024-04-15 00:00:00','Hàn Quốc','Skin1004','8938501230264','pieces',5,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(27,'Nước tẩy trang Bioderma Sensibio H2O hồng 500ml','Nước tẩy trang dịu nhẹ cho da nhạy cảm số 1 tại Pháp, công nghệ micellar water làm sạch sâu lớp makeup và bụi bẩn mà không làm khô da.',18.00,45,'/uploads/products/product-27.jpg','2027-02-01 00:00:00','2024-02-01 00:00:00','Pháp','Bioderma','8938501230271','pieces',5,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(28,'Kem dưỡng phục hồi da Dear Klairs Midnight Blue 60ml','Chiết xuất cúc La Mã Guaiazulene sắc xanh tự nhiên giúp làm dịu làn da cháy nắng hoặc sau tổn thương mụn, dưỡng ẩm sâu ban đêm.',22.00,35,'/uploads/products/product-28.jpg','2027-03-10 00:00:00','2024-03-10 00:00:00','Hàn Quốc','Dear, Klairs','8938501230288','pieces',5,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(29,'Son kem lì Black Rouge Air Fit Velvet Tint Ver 8','Chất son velvet nhung xốp mịn lướt nhẹ trên môi, khả năng bám màu lâu trôi, sắc son thời thượng không lộ vân môi.',11.50,85,'/uploads/products/product-29.jpg','2027-04-20 00:00:00','2024-04-20 00:00:00','Hàn Quốc','Black Rouge','8938501230295','pieces',5,'2026-09-24 10:46:47','2026-09-24 10:46:47'),(30,'Sữa rửa mặt tạo bọt CeraVe Foaming Cleanser 473ml','Chứa 3 loại Ceramide thiết yếu, Niacinamide và Hyaluronic Acid giúp loại bỏ bã nhờn dư thừa mà không phá vỡ hàng rào ẩm tự nhiên của da.',17.50,40,'/uploads/products/product-30.jpg','2027-01-25 00:00:00','2024-01-25 00:00:00','Mỹ (USA)','CeraVe','8938501230301','pieces',5,'2026-09-24 10:46:47','2026-09-24 10:46:47');
